CREATE TABLE IF NOT EXISTS `1776400480_wp_wc_admin_notes` ( `note_id` bigint unsigned NOT NULL AUTO_INCREMENT, `name` varchar(255) COLLATE utf8mb4_unicode_520_ci NOT NULL, `type` varchar(20) COLLATE utf8mb4_unicode_520_ci NOT NULL, `locale` varchar(20) COLLATE utf8mb4_unicode_520_ci NOT NULL, `title` longtext COLLATE utf8mb4_unicode_520_ci NOT NULL, `content` longtext COLLATE utf8mb4_unicode_520_ci NOT NULL, `content_data` longtext COLLATE utf8mb4_unicode_520_ci, `status` varchar(200) COLLATE utf8mb4_unicode_520_ci NOT NULL, `source` varchar(200) COLLATE utf8mb4_unicode_520_ci NOT NULL, `date_created` datetime NOT NULL DEFAULT '0000-00-00 00:00:00', `date_reminder` datetime DEFAULT NULL, `is_snoozable` tinyint(1) NOT NULL DEFAULT '0', `layout` varchar(20) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '', `image` varchar(200) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL, `is_deleted` tinyint(1) NOT NULL DEFAULT '0', `is_read` tinyint(1) NOT NULL DEFAULT '0', `icon` varchar(200) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'info', PRIMARY KEY (`note_id`)) ENGINE=InnoDB AUTO_INCREMENT=150 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;
INSERT INTO `1776400480_wp_wc_admin_notes` (`note_id`, `name`, `type`, `locale`, `title`, `content`, `content_data`, `status`, `source`, `date_created`, `date_reminder`, `is_snoozable`, `layout`, `image`, `is_deleted`, `is_read`, `icon`) VALUES (1,'wayflyer_bnpl_q4_2021','marketing','en_US','Grow your business with funding through Wayflyer','Fast, flexible financing to boost cash flow and help your business grow – one fee, no interest rates, penalties, equity, or personal guarantees. Based on your store’s performance, Wayflyer provides funding and analytical insights to invest in your business.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(2,'wc_shipping_mobile_app_usps_q4_2021','marketing','en_US','Print and manage your shipping labels with WooCommerce Shipping and the WooCommerce Mobile App','Save time by printing, purchasing, refunding, and tracking shipping labels generated by <a href=\"https://woocommerce.com/woocommerce-shipping/\">WooCommerce Shipping</a> – all directly from your mobile device!','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(3,'your-first-product','info','en_US','Your first product','That’s huge! You’re well on your way to building a successful online store — now it’s time to think about how you’ll fulfill your orders.<br /><br />Read our shipping guide to learn best practices and options for putting together your shipping strategy. And for WooCommerce stores in the United States, you can print discounted shipping labels via USPS with <a href=\"https://href.li/?https://woocommerce.com/shipping\" target=\"_blank\">WooCommerce Shipping</a>.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(4,'wc-admin-optimizing-the-checkout-flow','info','en_US','Optimizing the checkout flow','It’s crucial to get your store’s checkout as smooth as possible to avoid losing sales. Let’s take a look at how you can optimize the checkout experience for your shoppers.','{}','unactioned','woocommerce.com','2024-09-09 04:49:43',NULL,0,'plain','',0,0,'info'),(5,'wc-payments-qualitative-feedback','info','en_US','WooPayments setup - let us know what you think','Congrats on enabling WooPayments for your store. Please share your feedback in this 2 minute survey to help us improve the setup process.','{}','unactioned','woocommerce.com','2024-08-20 02:40:03',NULL,0,'plain','',1,1,'info'),(6,'share-your-feedback-on-paypal','info','en_US','Share your feedback on PayPal','Share your feedback in this 2 minute survey about how we can make the process of accepting payments more useful for your store.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(7,'google_listings_and_ads_install','marketing','en_US','Drive traffic and sales with Google','Reach online shoppers to drive traffic and sales for your store by showcasing products across Google, for free or with ads.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(8,'wc-subscriptions-security-update-3-0-15','info','en_US','WooCommerce Subscriptions security update!','We recently released an important security update to WooCommerce Subscriptions. To ensure your site’s data is protected, please upgrade <strong>WooCommerce Subscriptions to version 3.0.15</strong> or later.<br /><br />Click the button below to view and update to the latest Subscriptions version, or log in to <a href=\"https://woocommerce.com/my-dashboard\">WooCommerce.com Dashboard</a> and navigate to your <strong>Downloads</strong> page.<br /><br />We recommend always using the latest version of WooCommerce Subscriptions, and other software running on your site, to ensure maximum security.<br /><br />If you have any questions we are here to help — just <a href=\"https://woocommerce.com/my-account/create-a-ticket/\">open a ticket</a>.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(9,'woocommerce-core-update-5-4-0','info','en_US','Update to WooCommerce 5.4.1 now','WooCommerce 5.4.1 addresses a checkout issue discovered in WooCommerce 5.4. We recommend upgrading to WooCommerce 5.4.1 as soon as possible.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(10,'wcpay-promo-2020-11','marketing','en_US','wcpay-promo-2020-11','wcpay-promo-2020-11','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(11,'wcpay-promo-2020-12','marketing','en_US','wcpay-promo-2020-12','wcpay-promo-2020-12','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(12,'ppxo-pps-upgrade-paypal-payments-1','info','en_US','Get the latest PayPal extension for WooCommerce','Heads up! There’s a new PayPal on the block!<br /><br />Now is a great time to upgrade to our latest <a href=\"https://woocommerce.com/products/woocommerce-paypal-payments/\" target=\"_blank\">PayPal extension</a> to continue to receive support and updates with PayPal.<br /><br />Get access to a full suite of PayPal payment methods, extensive currency and country coverage, and pay later options with the all-new PayPal extension for WooCommerce.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(13,'ppxo-pps-upgrade-paypal-payments-2','info','en_US','Upgrade your PayPal experience!','Get access to a full suite of PayPal payment methods, extensive currency and country coverage, offer subscription and recurring payments, and the new PayPal pay later options.<br /><br />Start using our <a href=\"https://woocommerce.com/products/woocommerce-paypal-payments/\" target=\"_blank\">latest PayPal today</a> to continue to receive support and updates.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(14,'woocommerce-core-sqli-july-2021-need-to-update','update','en_US','Action required: Critical vulnerabilities in WooCommerce','In response to a critical vulnerability identified on July 13, 2021, we are working with the WordPress Plugins Team to deploy software updates to stores running WooCommerce (versions 3.3 to 5.5) and the WooCommerce Blocks feature plugin (versions 2.5 to 5.5).<br /><br />Our investigation into this vulnerability is ongoing, but <strong>we wanted to let you know now about the importance of updating immediately</strong>.<br /><br />For more information on which actions you should take, as well as answers to FAQs, please urgently review our blog post detailing this issue.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(15,'woocommerce-blocks-sqli-july-2021-need-to-update','update','en_US','Action required: Critical vulnerabilities in WooCommerce Blocks','In response to a critical vulnerability identified on July 13, 2021, we are working with the WordPress Plugins Team to deploy software updates to stores running WooCommerce (versions 3.3 to 5.5) and the WooCommerce Blocks feature plugin (versions 2.5 to 5.5).<br /><br />Our investigation into this vulnerability is ongoing, but <strong>we wanted to let you know now about the importance of updating immediately</strong>.<br /><br />For more information on which actions you should take, as well as answers to FAQs, please urgently review our blog post detailing this issue.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(16,'woocommerce-core-sqli-july-2021-store-patched','update','en_US','Solved: Critical vulnerabilities patched in WooCommerce','In response to a critical vulnerability identified on July 13, 2021, we worked with the WordPress Plugins Team to deploy software updates to stores running WooCommerce (versions 3.3 to 5.5) and the WooCommerce Blocks feature plugin (versions 2.5 to 5.5).<br /><br /><strong>Your store has been updated to the latest secure version(s)</strong>. For more information and answers to FAQs, please review our blog post detailing this issue.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(17,'woocommerce-blocks-sqli-july-2021-store-patched','update','en_US','Solved: Critical vulnerabilities patched in WooCommerce Blocks','In response to a critical vulnerability identified on July 13, 2021, we worked with the WordPress Plugins Team to deploy software updates to stores running WooCommerce (versions 3.3 to 5.5) and the WooCommerce Blocks feature plugin (versions 2.5 to 5.5).<br /><br /><strong>Your store has been updated to the latest secure version(s)</strong>. For more information and answers to FAQs, please review our blog post detailing this issue.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(18,'habit-moment-survey','marketing','en_US','We’re all ears! Share your experience so far with WooCommerce','We’d love your input to shape the future of WooCommerce together. Feel free to share any feedback, ideas or suggestions that you have.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(19,'woocommerce-core-paypal-march-2022-updated','update','en_US','Security auto-update of WooCommerce','<strong>Your store has been updated to the latest secure version of WooCommerce</strong>. We worked with WordPress to deploy PayPal Standard security updates for stores running WooCommerce (version 3.5 to 6.3). It’s recommended to disable PayPal Standard, and use <a href=\"https://woocommerce.com/products/woocommerce-paypal-payments/\" target=\"_blank\">PayPal Payments</a> to accept PayPal.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(20,'woocommerce-core-paypal-march-2022-updated-nopp','update','en_US','Security auto-update of WooCommerce','<strong>Your store has been updated to the latest secure version of WooCommerce</strong>. We worked with WordPress to deploy security updates related to PayPal Standard payment gateway for stores running WooCommerce (version 3.5 to 6.3).','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(21,'pinterest_03_2022_update','marketing','en_US','Your Pinterest for WooCommerce plugin is out of date!','Update to the latest version of Pinterest for WooCommerce to continue using this plugin and keep your store connected with Pinterest. To update, visit <strong>Plugins &gt; Installed Plugins</strong>, and click on “update now” under Pinterest for WooCommerce.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(22,'store_setup_survey_survey_q2_2022','survey','en_US','How is your store setup going?','Our goal is to make sure you have all the right tools to start setting up your store in the smoothest way possible.\r\nWe’d love to know if we hit our mark and how we can improve. To collect your thoughts, we made a 2-minute survey.','{}','unactioned','woocommerce.com','2024-08-27 01:42:13',NULL,0,'plain','',1,1,'info'),(23,'needs-update-eway-payment-gateway-rin-2022-12-20','update','en_US','Security vulnerability patched in WooCommerce Eway Gateway','In response to a potential vulnerability identified in WooCommerce Eway Gateway versions 3.1.0 to 3.5.0, we’ve worked to deploy security fixes and have released an updated version.\r\nNo external exploits have been detected, but we recommend you update to your latest supported version 3.1.26, 3.2.3, 3.3.1, 3.4.6, or 3.5.1','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(24,'updated-eway-payment-gateway-rin-2022-12-20','update','en_US','WooCommerce Eway Gateway has been automatically updated','Your store is now running the latest secure version of WooCommerce Eway Gateway. We worked with the WordPress Plugins team to deploy a software update to stores running WooCommerce Eway Gateway (versions 3.1.0 to 3.5.0) in response to a security vulnerability that was discovered.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(25,'ecomm-wc-navigation-survey-2023','info','en_US','Navigating WooCommerce on WordPress.com','We are improving the WooCommerce navigation on WordPress.com and would love your help to make it better! Please share your experience with us in this 2-minute survey.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(26,'woopay-beta-merchantrecruitment-04MAY23','info','en_US','Increase conversions with WooPay — our fastest checkout yet','WooPay, a new express checkout feature built into WooCommerce Payments, is now available —and we’re inviting you to be one of the first to try it. \r\n<br><br>\r\nBoost conversions by offering your customers a simple, secure way to pay with a single click.\r\n<br><br>\r\nGet started in seconds.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(27,'woocommerce-wcpay-march-2023-update-needed','update','en_US','Action required: Security update for WooCommerce Payments','<strong>Your store requires a security update for WooCommerce Payments</strong>. Please update to the latest version of WooCommerce Payments immediately to address a potential vulnerability discovered on March 22. For more information on how to update, visit this WooCommerce Developer Blog Post.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(28,'tap_to_pay_iphone_q2_2023_no_wcpay','marketing','en_US','Accept in-person contactless payments on your iPhone','Tap to Pay on iPhone and WooCommerce Payments is quick, secure, and simple to set up — no extra terminals or card readers are needed. Accept contactless debit and credit cards, Apple Pay, and other NFC digital wallets in person.','{}','unactioned','woocommerce.com','2024-08-25 09:00:59',NULL,0,'plain','',1,1,'info'),(29,'woocommerce-WCPreOrders-april-2023-update-needed','update','en_US','Action required: Security update of WooCommerce Pre-Orders extension','<strong>Your store requires a security update for the WooCommerce Pre-Orders extension</strong>. Please update the WooCommerce Pre-Orders extension immediately to address a potential vulnerability discovered on April 11.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(30,'woopay-beta-merchantrecruitment-update-04MAY23','info','en_US','Increase conversions with WooPay — our fastest checkout yet','WooPay, a new express checkout feature built into WooCommerce Payments, is now available — and you’re invited to try it. \r\n<br /><br />\r\nBoost conversions by offering your customers a simple, secure way to pay with a single click.\r\n<br /><br />\r\nUpdate WooCommerce Payments to get started.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(31,'woopay-beta-existingmerchants-noaction-27APR23','info','en_US','WooPay is back!','Thanks for previously trying WooPay, the express checkout feature built into WooCommerce Payments. We’re excited to announce that WooPay availability has resumed. No action is required on your part.\r\n<br /><br />\r\nYou can now continue boosting conversions by offering your customers a simple, secure way to pay with a single click.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(32,'woopay-beta-existingmerchants-update-27APR23','info','en_US','WooPay is back!','Thanks for previously trying WooPay, the express checkout feature built into WooCommerce Payments. We’re excited to announce that WooPay availability has resumed.\r\n<br /><br />\r\n\r\nUpdate to the latest WooCommerce Payments version to continue boosting conversions by offering your customers a simple, secure way to pay with a single click.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(33,'woopay-beta-merchantrecruitment-short-04MAY23','info','en_US','Increase conversions with WooPay — our fastest checkout yet','Be one of the first to try WooPay, a new express checkout feature for WooCommerce Payments. \r\n<br><br>\r\nBoost conversions by letting customers pay with a single click.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(34,'woopay-beta-merchantrecruitment-short-update-04MAY23','info','en_US','Increase conversions with WooPay — our fastest checkout yet','Be one of the first to try WooPay, our new express checkout feature. <br>Boost conversions by letting customers pay with a single click. <br><br>Update to the latest version of WooCommerce Payments to get started.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(35,'woopay-beta-merchantrecruitment-short-06MAY23-TESTA','info','en_US','Increase conversions with WooPay — our fastest checkout yet','Be one of the first to try WooPay, a new express checkout feature for WooCommerce Payments. \r\n<br><br>\r\nBoost conversions by letting customers pay with a single click.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(36,'woopay-beta-merchantrecruitment-short-06MAY23-TESTB','info','en_US','Increase conversions with WooPay — our fastest checkout yet','Be one of the first to try WooPay, a new express checkout feature for WooCommerce Payments. \r\n<br><br>\r\nBoost conversions by letting customers pay with a single click.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(37,'woopay-beta-merchantrecruitment-short-06MAY23-TESTC','info','en_US','Increase conversions with WooPay — our fastest checkout yet','Be one of the first to try WooPay, a new express checkout feature for WooCommerce Payments. \r\n<br><br>\r\nBoost conversions by letting customers pay with a single click.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(38,'woopay-beta-merchantrecruitment-short-06MAY23-TESTD','info','en_US','Increase conversions with WooPay — our fastest checkout yet','Be one of the first to try WooPay, a new express checkout feature for WooCommerce Payments. \r\n<br><br>\r\nBoost conversions by letting customers pay with a single click.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(39,'woopay-beta-merchantrecruitment-short-09MAY23','info','en_US','Increase conversions with WooPay — our fastest checkout yet','Be one of the first to try WooPay, a new express checkout feature for WooCommerce Payments. \r\n<br><br>\r\nBoost conversions by letting customers pay with a single click.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(40,'woopay-beta-merchantrecruitment-short-update-09MAY23','info','en_US','Increase conversions with WooPay — our fastest checkout yet','Be one of the first to try WooPay, our new express checkout feature. <br>Boost conversions by letting customers pay with a single click. <br><br>Update to the latest version of WooCommerce Payments to get started.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(41,'woocommerce-WCSubscriptions-June-2023-updated-needed','marketing','en_US','Action required: Security update of WooCommerce Subscriptions','<strong>Your store requires a security update for the WooCommerce Subscriptions plugin</strong>. Please update the WooCommerce Subscriptions plugin immediately to address a potential vulnerability.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(42,'woocommerce-WCReturnsWarranty-June-2023-updated-needed','update','en_US','Action required: Security update of WooCommerce Returns and Warranty Requests extension','<strong>Your store requires a security update for the Returns and Warranty Requests extension</strong>.  Please update to the latest version of the WooCommerce Returns and Warranty Requests extension immediately to address a potential vulnerability discovered on May 31.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(43,'woocommerce-WCOPC-June-2023-updated-needed','update','en_US','Action required: Security update of WooCommerce One Page Checkout','<strong>Your shop requires a security update to address a vulnerability in the WooCommerce One Page Checkout extension</strong>. The fix for this vulnerability was released for this extension on June 13th. Please update immediately.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(44,'woocommerce-WCGC-July-2023-update-needed','update','en_US','Action required: Security update of WooCommerce GoCardless Extension','<strong>Your shop requires a security update to address a vulnerability in the WooCommerce GoCardless extension</strong>. The fix for this vulnerability was released on July 4th. Please update immediately.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(45,'woocommerce-shipping-fedex-api-outage-2023-07-16','warning','en_US','Scheduled FedEx API outage — July 2023','On July 16 there will be a full outage of the FedEx API from 04:00 to 08:00 AM UTC. Due to planned maintenance by FedEx, you\'ll be unable to provide FedEx shipping rates during this time. Follow the link below for more information and recommendations on how to minimize impact.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(46,'wcship-2023-07-hazmat-update-needed','update','en_US','Action required: USPS HAZMAT compliance update for WooCommerce Shipping & Tax extension','<strong>Your store requires an update for the WooCommerce Shipping extension</strong>. Please update to the latest version of the WooCommerce Shipping &amp; Tax extension immediately to ensure compliance with new USPS HAZMAT rules currently in effect.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(47,'woocommerce-WCStripe-Aug-2023-update-needed','update','en_US','Action required: Security update for WooCommerce Stripe plugin','<strong>Your shop requires an important security update for the  WooCommerce Stripe plugin</strong>. The fix for this vulnerability was released on July 31. Please update immediately.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(48,'woocommerce-WCStripe-Aug-2023-security-updated','update','en_US','Security update of WooCommerce Stripe plugin','<strong>Your store has been updated to the latest secure version of the WooCommerce Stripe plugin</strong>. This update was released on July 31.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(49,'woocommerce-WooPayments-Aug-2023-security-updated','update','en_US','Security update of WooPayments (WooCommerce Payments) plugin','<strong>Your store has been updated to the more secure version of WooPayments (WooCommerce Payments)</strong>. This update was released on July 31.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(50,'avalara_q3-2023_noAvaTax','marketing','en_US','Automatically calculate VAT in real time','Take the effort out of determining tax rates and sell confidently across borders with automated tax management from Avalara AvaTax— including built-in VAT calculation when you sell into or across the EU and UK. Save time and stay compliant when you let Avalara do the heavy lifting.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(51,'woo-activation-survey-blockers-22AUG23','info','en_US','How can we help you get that first sale?','Your feedback is vital. Please take a minute to share your experience of setting up your new store and whether anything is preventing you from making those first few sales. Together, we can make Woo even better!','{}','unactioned','woocommerce.com','2024-08-21 13:17:30',NULL,0,'plain','',1,1,'info'),(52,'woocommerce-usermeta-Sept2023-productvendors','update','en_US','Your store requires a security update','<strong>Your shop needs an update to address a vulnerability in WooCommerce.</strong> The fix was released on Sept 15. Please update WooCommerce to the latest version immediately. <a href=\"https://developer.woocommerce.com/2023/09/16/woocommerce-vulnerability-reintroduced-from-7-0-1/\" />Read our developer update</a> for more information.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(53,'woocommerce-STRIPE-Oct-2023-update-needed','update','en_US','Action required: Security update for WooCommerce Stripe Gateway','<strong>Your shop requires a security update to address a vulnerability in the WooCommerce Stripe Gateway</strong>. The fix for this vulnerability was released on October 17. Please update immediately.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(54,'amazon-mcf-reviews-2023-12-07','marketing','en_US','Enjoying Amazon MCF for WooCommerce?','We\'re Never Settle, the developers behind Amazon MCF for WooCommerce, and would be deeply honored to have your review. Reviews help immensely as other users can learn how MCF can solve their needs too! Not happy or need help? Please reach out for support and we’d love to make things right!','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(55,'remove_estimated_deposits_2024','marketing','en_US','Estimated deposits are going away','To provide more accurate deposit information and support the expansion of instant deposits, estimated deposit details will no longer be available in WooPayments. We recommend upgrading to the latest version of WooPayments for more detailed balance status information.','{}','pending','woocommerce.com','2024-08-20 00:24:22',NULL,0,'plain','',0,0,'info'),(56,'wc-refund-returns-page','info','en_US','Setup a Refund and Returns Policy page to boost your store\'s credibility.','We have created a sample draft Refund and Returns Policy page for you. Please have a look and update it to fit your store.','{}','unactioned','woocommerce-core','2024-08-20 01:13:37',NULL,0,'plain','',1,1,'info'),(57,'storefront-customize','info','en_US','Design your store with Storefront 🎨','Visit the Storefront settings page to start setup and customization of your shop.','{}','unactioned','storefront','2024-08-20 01:13:40',NULL,0,'plain','',1,1,'info'),(59,'wcpay-promo-2023-action-discount','info','en_US','-','-','{}','actioned','woocommerce','2024-08-20 01:20:04',NULL,0,'plain','',0,0,'info'),(64,'wc-admin-launch-checklist','info','en_US','Ready to launch your store?','To make sure you never get that sinking \"what did I forget\" feeling, we\'ve put together the essential pre-launch checklist.','{}','unactioned','woocommerce-admin','2024-08-21 04:39:11',NULL,0,'plain','',1,1,'info'),(65,'wc-admin-mobile-app','info','en_US','Install Woo mobile app','Install the WooCommerce mobile app to manage orders, receive sales notifications, and view key metrics — wherever you are.','{}','unactioned','woocommerce-admin','2024-08-22 00:42:59',NULL,0,'plain','',1,1,'info'),(66,'wc-admin-customizing-product-catalog','info','en_US','How to customize your product catalog','You want your product catalog and images to look great and align with your brand. This guide will give you all the tips you need to get your products looking great in your store.','{}','unactioned','woocommerce-admin','2024-08-23 00:26:41',NULL,0,'plain','',1,1,'info'),(67,'wc-admin-marketing-jetpack-backup','marketing','en_US','Protect your WooCommerce Store with Jetpack Backup.','Store downtime means lost sales. One-click restores get you back online quickly if something goes wrong.','[]','unactioned','woocommerce-admin-notes','2024-08-23 00:26:41',NULL,0,'thumbnail','https://mhc.lxf.temporary.site/website_b3635980/wp-content/plugins/woocommerce/assets/images/admin_notes/marketing-jetpack-2x.png',1,1,'info'),(68,'wc-admin-onboarding-payments-reminder','info','en_US','Start accepting payments on your store!','Take payments with the provider that’s right for you - choose from 100+ payment gateways for WooCommerce.','{}','unactioned','woocommerce-admin','2024-08-25 03:06:49',NULL,0,'plain','',1,1,'info'),(69,'wc-update-db-reminder','update','en_US','WooCommerce database update done','WooCommerce database update complete. Thank you for updating to the latest version!','{}','actioned','woocommerce-core','2024-08-25 06:23:17',NULL,0,'plain','',0,1,'info'),(70,'wc-admin-woocommerce-payments','marketing','en_US','Try the new way to get paid','Securely accept credit and debit cards on your site. Manage transactions without leaving your WordPress dashboard. Only with <strong>WooPayments</strong>.<br><br>By clicking \"Get started\", you agree to our <a href=\"https://wordpress.com/tos/\" target=\"_blank\">Terms of Service</a>','{}','actioned','woocommerce-admin','2024-08-27 01:42:13',NULL,0,'plain','',0,0,'info'),(71,'bfcm2024-landing-page','marketing','en_US','The best way to prepare for holiday success','The upcoming holiday season is the busiest time of the year for many online stores. We want to help you make the most of it with an early gift: our first-ever Black Friday Cyber Monday Trends Report. It\'s full of stats, trends, and recommendations to knock your holiday socks off!','{}','pending','woocommerce.com','2024-09-05 00:27:15',NULL,0,'plain','',0,0,'info'),(72,'wc-admin-orders-milestone','info','en_US','First order received','Congratulations on getting your first order! Now is a great time to learn how to manage your orders.','{\"current_milestone\":1}','unactioned','woocommerce-admin','2024-09-13 11:24:23',NULL,0,'plain','',0,0,'info'),(73,'stripe_securityupdate_q3_2024','update','en_US','Security update required for your Stripe extension','To continue securely accepting payments, you must update your Stripe extension to at least version 8.6, re-authenticate, and turn on the new checkout experience. Review the documentation for instructions on how to make the necessary changes from your WooCommerce dashboard.','{}','pending','woocommerce.com','2024-09-19 00:24:20',NULL,0,'plain','',0,0,'info'),(74,'paypal_migration_Q3_2024','marketing','en_US','You’re using an outdated version of PayPal','Don\'t miss out on potential sales this holiday season — upgrade your store\'s checkout experience by switching to the all-in-one PayPal Payments extension. Enable customers to pay using Venmo and Pay Later (where available), credit and debit cards, Apple Pay, Google Pay, and country-specific options.','{}','pending','woocommerce.com','2024-10-04 00:45:32',NULL,0,'plain','',0,0,'info'),(75,'paypal_migration_Q3_2024_v2','marketing','en_US','You’re using an outdated version of PayPal','Don\'t miss out on potential sales this holiday season — upgrade your store\'s checkout experience by switching to the all-in-one PayPal Payments extension. Enable customers to pay using Venmo and Pay Later (where available), credit and debit cards, Apple Pay, Google Pay, and country-specific options.','{}','pending','woocommerce.com','2024-10-31 00:49:02',NULL,0,'plain','',0,0,'info'),(76,'mollie_q4_2024','marketing','en_US','Special offer: Zero transaction fees for your first month with Mollie','With seamless checkout, flexible financing, and 30+ local and global payment methods, Mollie is the all-in-one payment solution that enhances the customer experience and helps your business grow. Start your account today and enjoy ZERO transaction fees for the first month. Ts&amp;Cs apply.','{}','pending','woocommerce.com','2024-11-01 00:42:50',NULL,0,'plain','',0,0,'info'),(77,'wc-admin-real-time-order-alerts','info','en_US','Get real-time order alerts anywhere','Get notifications about store activity, including new orders and product reviews directly on your mobile devices with the Woo app.','{}','unactioned','woocommerce-admin','2024-11-18 01:12:29',NULL,0,'plain','',0,0,'info'),(78,'Renewal_notification_emails_Woosubscriptions_Nov2024','marketing','en_US','WooCommerce Subscriptions just got even better','You can now send automatic email reminders to customers before their subscriptions renew or expire. To enable this for your store, update to the latest version of WooCommerce Subscriptions (don\'t forget to make a backup first) and follow the steps linked below.','{}','pending','woocommerce.com','2024-11-19 00:26:35',NULL,0,'plain','',0,0,'info'),(80,'paypal_promo_Q4_2024','marketing','en_US','Add PayPal to your existing checkout this holiday season','Drive conversion and give customers more confidence to buy when you complement your checkout with PayPal, Venmo, Pay Later, and more. Attract new shoppers and give them a streamlined buying experience with Fastlane, PayPal’s fast and simple guest checkout.','{}','pending','woocommerce.com','2024-11-28 00:27:00',NULL,0,'plain','',0,0,'info'),(81,'sirt-woo-2024-11-xss-admin','update','en_US','An important update is required for WooCommerce','This update addresses a security vulnerability that could allow unauthorized access to administrative privileges on your site. <a href=\"https://developer.woocommerce.com/2024/12/03/woocommerce-9-4-3-and-woocommerce-9-3-4-available-now/\">Learn more</a>.\r\n<br><br>\r\n<strong>Please ensure your site is updated to the latest version to stay secure.</strong>','{}','pending','woocommerce.com','2024-12-04 00:26:21',NULL,0,'plain','',0,0,'info'),(82,'usps-mail-service-to-canada-suspended-dec-2024','update','en_US','Please note: USPS Mail Service to Canada Suspended','The United States Postal Service has temporarily suspended mail service to Canada due to the ongoing Canadian postal workers\' strike. USPS is asking users to refrain from mailing items to Canada at this time.','{}','unactioned','woocommerce.com','2024-12-06 01:00:22',NULL,0,'plain','',0,0,'info'),(83,'Announce-UPS-WCShipping-Dec2024','marketing','en_US','WooCommerce Shipping now supports select UPS services','Give customers the power and reliability of UPS, directly from your dashboard. Access discounted rates, convenient shipping options, and fast, on-time delivery with UPS on WooCommerce Shipping — and stay tuned for UPS® Ground Saver rates coming in 2025.','{}','pending','woocommerce.com','2024-12-13 01:42:17',NULL,0,'plain','',0,0,'info'),(84,'account-creation-after-checkout-dec2024','marketing','en_US','Offer account creation after checkout','Your customers can now create accounts after they check out on block-based themes. Enable the new “After checkout” block in your account settings and enjoy smoother guest checkout, better conversion, and more repeat business.','{}','pending','woocommerce.com','2024-12-19 00:40:35',NULL,0,'plain','',0,0,'info'),(85,'woocommerce-analytics-order-attribution-promotions-december-2024','marketing','en_US','Discover what drives your sales','Use our powerful <strong>Order Attribution</strong> extension to understand what truly drives your revenue. Track your sales journey, identify your most effective marketing channels, and optimize your sales strategy.','{}','unactioned','woocommerce.com','2025-02-25 00:29:05',NULL,0,'plain','',0,1,'info'),(86,'affirm_promo_Q1_2025','marketing','en_US','Save up to 50% on merchant fees with Affirm','Kickstart the year with buy now, pay later and get merchant rates as low as 2.9% + 30¢ per transaction for 30 days. Download the extension and complete your application from your WooCommerce dashboard by February 19, 2025 to claim the offer. Terms and conditions apply.','{}','pending','woocommerce.com','2025-01-21 01:47:34',NULL,0,'plain','',0,0,'info'),(87,'new-woo-brand-announcement-feb4-2025','marketing','en_US','Meet the new Woo','WooCommerce has a new look, but underneath, we’re still the same customizable, open-source ecommerce platform you know and love. Plus, we’ve got some major improvements to our platform and product on the way.','{}','pending','woocommerce.com','2025-02-05 00:38:52',NULL,0,'plain','',0,0,'info'),(88,'paypal_bnpl_au_promo_Q1_2025','marketing','en_US','Australian shoppers can Pay in 4 with PayPal','Enable Pay in 4 messaging to let Australian customers know that they can pay over time while you get paid up front and in full. Pay in 4 is included in PayPal Payments at no additional cost. Eligible buyers can pay in four interest-free payments for purchases of $30 to $2,000 AUD. Terms apply.','{}','pending','woocommerce.com','2025-02-12 00:33:08',NULL,0,'plain','',0,0,'info'),(89,'wc-admin-manage-orders-on-the-go','info','en_US','Manage your orders on the go','Look for orders, customer info, and process refunds in one click with the Woo app.','{}','unactioned','woocommerce-admin','2025-02-16 01:44:32',NULL,0,'plain','',0,1,'info'),(90,'stripe_stripetax_q1_2025','marketing','en_US','Say goodbye to your tax woes','Stripe Tax automatically applies the correct sales tax, VAT, or GST, saving time while keeping you compliant. And with simple automatic filing, you can stop stressing at tax time and focus on growing instead.','{}','pending','woocommerce.com','2025-02-20 00:28:38',NULL,0,'plain','',0,0,'info'),(91,'printful_promo_q1_2025','marketing','en_US','New: sell print-on-demand products, risk-free','Expand your product line with Printful, now available in the WooCommerce Marketplace. Sell custom products with no upfront costs or inventory. This trusted supplier prints, packages, and ships for you, so you can focus on growing your store — and your next big idea.','{}','pending','woocommerce.com','2025-02-26 00:29:24',NULL,0,'plain','',0,0,'info'),(92,'paypal-braintree-sdk-depreciation-2025-02-20','update','en_US','Update required for your PayPal Braintree extension','To continue securely accepting payments, you must update your PayPal Braintree extension to version 3.2.4 or newer before June 30, 2025. Your current extension version will not support payment processing after this date due to an SSL certificate update.','{}','pending','woocommerce.com','2025-03-04 00:26:30',NULL,0,'plain','',0,0,'info'),(93,'woo-marketplace-two-year-subscriptions-rin-2025-03-17','marketing','en_US','Save 20% on new two-year subscriptions','We’ve introduced 20% off two-year subscriptions for all products* in the WooCommerce Marketplace. Lock in long-term savings and make sure your store never misses a beat. \r\n\r\n*Some exclusions apply. New purchases only.','{}','pending','woocommerce.com','2025-03-17 00:49:20',NULL,0,'plain','',0,0,'info'),(94,'viva_wallet_migration_q1_2025','update','en_US','Switch to the new Viva.com Smart Checkout','The Viva Wallet extension is no longer being updated and improved. To get the best Viva.com experience, move to the new Smart Checkout. It’s fast, secure, and fully compatible with the latest WooCommerce features.','{}','pending','woocommerce.com','2025-04-04 01:01:04',NULL,0,'plain','',0,0,'info'),(95,'stripe_orderstatus_bug_q2_2025','update','en_US','Action Required: Update Order Status Manager','Update to the latest Order Status Manager (v1.15.5+) to ensure payments are captured. Your version of WooCommerce Order Status Manager can interfere with order processing for payment gateways (including WooCommerce Stripe Gateway v9.2.0+), which may cause orders to process without capturing payment.','{}','pending','woocommerce.com','2025-04-04 01:01:04',NULL,0,'plain','',0,0,'info'),(96,'WooCommerce-Stripe-Gateway-Update-April-2025','update','en_US','Action required: Update WooCommerce Stripe Gateway to v9.4.1','<strong>An important update for WooCommerce Stripe Payment Gateway has been released</strong>. Version 9.4.1 addresses performance issues and payment method visibility problems that occurred in version 9.4.0. Please update as soon as possible for optimal store performance. Please read <a href=\"https://developer.woocommerce.com/2025/04/18/https://developer.woocommerce.com/2025/04/18/developer-advisory-stripe-payment-gateway-9-4-1-release/\" /> this advisory</a> for more information.','{}','pending','woocommerce.com','2025-04-19 00:25:35',NULL,0,'plain','',0,0,'info'),(97,'WooCommerce-Stripe-Gateway-Update-Info-April-2025','update','en_US','WooCommerce Stripe Gateway has been updated to v9.4.1','<strong>WooCommerce Stripe Payment Gateway was recently updated</strong>. Version 9.4.1 addresses performance issues and payment method visibility problems that occurred in version 9.4.0. No further action is required. Please read <a href=\"https://developer.woocommerce.com/2025/04/18/https://developer.woocommerce.com/2025/04/18/developer-advisory-stripe-payment-gateway-9-4-1-release/\" /> this advisory post </a>for more information.','{}','pending','woocommerce.com','2025-04-19 00:25:35',NULL,0,'plain','',0,0,'info'),(98,'klaviyo_q2_2025','marketing','en_US','Tailor your marketing with data-driven automation','Deliver personalized experiences at scale, simplify your stack, and make your data work for you using Klaviyo’s best-in-class marketing extension for Woo. With advanced segmentation based on actual customer behavior, you can send email and SMS messages that drive revenue and increase loyalty — without adding complexity','{}','pending','woocommerce.com','2025-04-30 00:33:56',NULL,0,'plain','',0,0,'info'),(99,'uk-vat-notice-2025-04-30','warning','en_US','UK VAT numbers are no longer supported','Due to recent HM Revenue &amp; Customs (HMRC) VAT API changes, your EU VAT Number for WooCommerce extension can no longer validate UK VAT numbers. HMRC now requires merchants to register an API key, which this extension does not currently support. We recommend EU/UK VAT Validation Manager for WooCommerce as a replacement','{}','pending','woocommerce.com','2025-05-06 00:32:09',NULL,0,'plain','',0,0,'info'),(100,'payson-retirement-2025','update','en_US','Payson Form Retirement','Svea Bank is discontinuing the Payson service; the last date for transactions is August 31, 2025. As a result, the Payson Form extension has been removed from WooCommerce.com. Documentation remains available.','{}','pending','woocommerce.com','2025-05-13 00:39:05',NULL,0,'plain','',0,0,'info'),(101,'wc-admin-performance-on-mobile','info','en_US','Track your store performance on mobile','Monitor your sales and high performing products with the Woo app.','{}','unactioned','woocommerce-admin','2025-05-17 00:25:27',NULL,0,'plain','',0,1,'info'),(102,'paypal_q2_2025','marketing','en_US','Power up sales with Pay Later messaging','Help increase your sales and grow cart sizes by letting customers know they have flexible payment options. Merchants see up to an 11% sales lift when they add Pay Later messaging — plus, it integrates seamlessly with your PayPal checkout.','{}','pending','woocommerce.com','2025-05-22 01:10:45',NULL,0,'plain','',0,0,'info'),(103,'paypal-braintree-sdk-depreciation-2025-05-30','update','en_US','Action required: Update the PayPal Braintree extension','Your PayPal Braintree extension is using an outdated SDK and will stop processing payments after June 30, 2025, due to a root SSL certificate expiration. To avoid service disruption, update to version 3.2.4 or newer immediately.','{}','pending','woocommerce.com','2025-05-30 00:51:52',NULL,0,'plain','',0,0,'info'),(104,'tento_q2_2025','marketing','en_US','Get your free business credit score','Strong business credit is the key to better deals, stronger partnerships, and sustainable growth. Tento Business Credit Monitoring helps you catch risks early, secure better financing, and fuel smarter growth — with no impact to your credit.','{}','pending','woocommerce.com','2025-06-05 01:34:36',NULL,0,'plain','',0,0,'info'),(105,'woopayments-multibanco-alipay-wechat-launch-2025-06-23','marketing','en_US','Multibanco, AliPay and WeChat now available in WooPayments','Multibanco, AliPay, and WeChat Pay are now available in WooPayments! Offer trusted local payment methods to customers in key global markets and boost international sales. Geo restrictions apply.','{}','pending','woocommerce.com','2025-06-24 00:25:09',NULL,0,'plain','',0,0,'info'),(106,'woopayments-new-lpms-2025-06-30','marketing','en_US','Get the POS built specifically for Woo stores','Introducing WooCommerce POS, our new point-of-sale solution built to get you up and running quickly with in-person sales. Search products, scan barcodes, apply coupons, and send email receipts — right in the WooCommerce mobile app, with all of your online and physical sales synced in real time — no extra setup required','{}','pending','woocommerce.com','2025-07-01 00:25:53',NULL,0,'plain','',0,0,'info'),(107,'tiktok-webinar-promo-july2025','marketing','en_US','You\'re Invited: TikTok for WooCommerce Webinar','Join us for a free webinar with our friends at TikTok on Tuesday, July 8, at 4 pm UTC. We\'ll cover creative tips and best practices for making content that turns views into sales.','{}','pending','woocommerce.com','2025-07-01 00:25:53',NULL,0,'plain','',0,0,'info'),(108,'woopayments-grabpay-launch-2025-07-07','marketing','en_US','GrabPay now available in WooPayments','Offer GrabPay through WooPayments and make checkout easier for customers across Southeast Asia. Enable it today and expand your reach with a payment method they know and trust.','{}','pending','woocommerce.com','2025-07-08 00:37:35',NULL,0,'plain','',0,0,'info'),(109,'BFCM-25-Survey','marketing','en_US','You’re invited: Take our quick BFCM survey and get 25% off','We’re gathering insights on how businesses prepare for peak sales moments like Black Friday and Cyber Monday — so we can better support you. Take our quick 8-minute survey to share your thoughts and get 25% off your next WooCommerce extension as a thank you.','{}','pending','woocommerce.com','2025-07-15 01:12:20',NULL,0,'plain','',0,0,'info'),(110,'woohoo10-coupon','marketing','en_US','Celebrate and save with WooCommerce 10.0','To mark this milestone release, get 10% off extensions and themes in the official Woo Marketplace. Use code WOOHOO10 at checkout to save on essential tools that help grow your business. Offer ends August 15, 2025. Terms and conditions apply.','{}','unactioned','woocommerce.com','2025-07-22 00:26:07',NULL,0,'plain','',0,1,'info'),(111,'paypaladvantage_q3_2025','marketing','en_US','Add PayPal Checkout and earn up to $1,000*','PayPal Checkout can boost conversion by up to 46% and average order value by up to 62% with no disruption to your checkout. New US merchants who activate by August 31 save 25% on transaction fees for 6 months. Excludes Venmo. Terms apply.*','{}','pending','woocommerce.com','2025-07-23 00:28:10',NULL,0,'plain','',0,0,'info'),(112,'wc-admin-email-improvements','info','en_US','Store emails have had an upgrade!','We’ve made some exciting improvements to our email templates, including modern, shopper-friendly designs and new customization options. And if you’re using a block theme, you can automatically sync your theme styles! Head to your email settings to explore the new features.','{}','unactioned','woocommerce-admin','2025-07-26 00:28:46',NULL,0,'plain','',0,0,'info'),(113,'wc-payments-notes-set-up-stripe-link','info','en_US','Increase conversion at checkout','Reduce cart abandonment and create a frictionless checkout experience with Link by Stripe. Link autofills your customer’s payment and shipping details, so they can check out in just six seconds with the Link optimized experience.','{}','unactioned','woocommerce-payments','2025-08-03 06:43:06',NULL,0,'plain','',0,0,'info'),(114,'wc-payments-notes-multi-currency-available','info','en_US','Sell worldwide in multiple currencies','Boost your international sales by allowing your customers to shop and pay in their local currency.','{}','unactioned','woocommerce-payments','2025-08-03 06:43:06',NULL,0,'plain','',0,0,'info'),(115,'om-wc-grow-revenue','info','en_US','Grow your store revenue with OptinMonster','Create high-converting OptinMonster campaigns to promote product sales, reduce cart abandonment and incentivize purchases with time-sensitive coupon offers.','{}','unactioned','optinmonster','2025-08-03 06:49:12',NULL,0,'plain','',0,0,'info'),(116,'wc-admin-wc-helper-subscription','warning','en_US','Table Rate Shipping subscription expiring soon','Your subscription expires in 29 days. Enable autorenew to avoid losing updates and access to support.','{\"product_id\":18718,\"product_name\":\"Table Rate Shipping\",\"expired\":false,\"days_until_expiration\":29}','unactioned','woocommerce-admin','2025-08-12 03:07:34',NULL,0,'plain','',0,0,'info'),(117,'wc-admin-wc-helper-subscription','warning','en_US','Quantity Discounts & Pricing subscription expiring soon','Your subscription expires in 23 days. Enable autorenew to avoid losing updates and access to support.','{\"product_id\":8232229,\"product_name\":\"Quantity Discounts & Pricing\",\"expired\":false,\"days_until_expiration\":23}','unactioned','woocommerce-admin','2025-08-12 03:07:34',NULL,0,'plain','',0,0,'info'),(118,'stripe_optimizedcheckout_upgrade_q3_2025','marketing','en_US','Upgrade for a faster, more flexible Stripe checkout','You\'re not on the latest WooCommerce Stripe Payment Gateway version. Upgrade to version 9.8 to access Stripe\'s Optimized Checkout Suite and leverage AI models to dynamically surface the most relevant payment methods for each customer, including BNPL, local options, and one-click Link checkout.','{}','pending','woocommerce.com','2025-08-14 00:42:40',NULL,0,'plain','',0,0,'info'),(119,'stripe_optimizedcheckout_enable_q3_2025','marketing','en_US','Unlock dynamic payments and sell more','You’re on the latest WooCommerce Stripe Payment Gateway — now unlock its full potential by enabling the Optimized Checkout Suite. It uses AI models to dynamically surface the most relevant payment methods for each customer, helping you boost conversions.','{}','pending','woocommerce.com','2025-08-14 00:42:40',NULL,0,'plain','',0,0,'info'),(120,'stripe_optimizedcheckout_promotion_q3_2025','marketing','en_US','Upgrade to Stripe for a faster, more flexible checkout','Unlock dynamic payments with Stripe’s Optimized Checkout Suite — now available with the WooCommerce Stripe Payment Gateway. Leverage AI models to dynamically surface the most relevant payment methods for each customer, including BNPL, local options, and one-click Link checkout.','{}','pending','woocommerce.com','2025-08-16 00:45:06',NULL,0,'plain','',0,0,'info'),(121,'wc-admin-edit-products-on-the-move','info','en_US','Edit products on the move','Edit and create new products from your mobile devices with the Woo app','{}','unactioned','woocommerce-admin','2025-08-20 00:47:24',NULL,0,'plain','',0,0,'info'),(122,'woo-subscription-gifting-bundling-2025-08-18','marketing','en_US','Grow recurring revenue with gifting','WooCommerce Subscriptions now includes gifting. Customers can buy subscriptions for others, helping you reach new shoppers and grow recurring revenue with less effort. Update to the latest version of Subscriptions (7.8.0) to start offering gifting.','{}','pending','woocommerce.com','2025-08-20 00:47:24',NULL,0,'plain','',0,0,'info'),(123,'stripe_optimizedcheckout_competitors_q3_2025','marketing','en_US','Upgrade to the official WooCommerce Stripe Payment Gateway','Unlock dynamic payments with Stripe’s Optimized Checkout Suite — now available with the WooCommerce Stripe Payment Gateway. Use AI models to dynamically surface the most relevant payment methods for each customer, including BNPL, local options, and one-click checkout with Link.','{}','pending','woocommerce.com','2025-08-28 22:24:21',NULL,0,'plain','',0,0,'info'),(125,'UPS-promo-RIN-WCS-Aug-25','marketing','en_US','Get up to $100 off your first UPS shipments','For a limited time, merchants new to UPS can get up to $10 off their first 10 UPS labels on WooCommerce Shipping. Simplify your shipping, lower costs, and keep customers happy with fast, affordable options built right into your store dashboard.','{}','unactioned','woocommerce.com','2025-09-11 00:56:00',NULL,0,'plain','',0,0,'info'),(126,'UPS-promo-RIN-WCST-Aug-25','marketing','en_US','Get up to $100 off your first UPS shipments','For a limited time, merchants new to UPS can get up to $10 off their first 10 UPS labels on WooCommerce Shipping. Simplify your shipping, lower costs, and keep customers happy with fast, affordable options built right into your store dashboard.','{}','unactioned','woocommerce.com','2025-09-11 00:56:00',NULL,0,'plain','',0,0,'info'),(127,'square_ordersync_upgrade_q3_2025','marketing','en_US','You asked, we delivered — order sync is here for Square','Update your Square extension to v5.0 to access <a href=\"https://woocommerce.com/document/woocommerce-square/sync-settings/sync-orders-between-woocommerce-and-square/\">automatic order syncing</a>. Manage your online sales in Square, keep reports accurate, and save time with order updates visible across both platforms.','{}','pending','woocommerce.com','2025-09-12 00:30:41',NULL,0,'plain','',0,0,'info'),(128,'klaviyo_q3_2025','marketing','en_US','Smarter marketing starts with Woo x Klaviyo','Personalize every customer interaction with Klaviyo, Woo\'s preferred marketing automation solution. Advanced segmentation based on real customer behavior lets you create email and SMS campaigns focused on driving loyalty and revenue. So you can grow sales while simplifying your stack.','{}','pending','woocommerce.com','2025-09-17 00:41:48',NULL,0,'plain','',0,0,'info'),(129,'pinterest_q3_20252','marketing','en_US','More visibility, smarter campaigns','Connect your store to Pinterest via the Conversions API, a new feature in the latest version of our official extension. Target the right shoppers, track performance, and optimize campaigns for more sales. Get started today — connect and sync your catalog using the Conversions API.','{}','pending','woocommerce.com','2025-09-24 00:33:53',NULL,0,'plain','',0,0,'info'),(130,'ppcp-settings-migration-inbox-note','info','en_US','📢 Important: New PayPal Payments settings UI becoming default in October!','We\'ve redesigned the settings for better performance and usability. Starting late October, this improved design will be the default for all WooCommerce installations to enjoy faster navigation, cleaner organization, and improved performance. Check out the <a href=\"https://woocommerce.com/document/woocommerce-paypal-payments/paypal-payments-startup-guide/\" target=\"_blank\">Startup Guide</a>, then click <a href=\"#\" name=\"settings-switch-ui\"><strong>Switch to New Settings</strong></a> to activate it.','{}','unactioned','woocommerce-paypal-payments/woocommerce-paypal-payments.php','2025-10-01 04:26:55',NULL,0,'plain','',0,0,'info'),(131,'pinterest_q4_2025','marketing','en_US','Maximize conversions with Pinterest','Connect your store to Pinterest via the Conversions API, now part of our official extension. Target the right shoppers, track performance, and optimize campaigns for more sales. Sync your catalog and create your first ad today.','{}','pending','woocommerce.com','2025-10-22 00:50:59',NULL,0,'plain','',0,0,'info'),(132,'paypaladvantage_q4_2025','marketing','en_US','PayPal Checkout offer: Get 40% back on fees for 3 months','Download and activate PayPal Payments in your WooCommerce admin, then complete your first transaction by 15 December 2025 to get 40% back on PayPal transaction fees — up to £2,000 for 3 months. PayPal Checkout works with your existing checkout. See terms: paypal.com/uk/campaign/paypalmerchantpromotion/terms.','{}','pending','woocommerce.com','2025-11-05 00:37:10',NULL,0,'plain','',0,0,'info'),(133,'reddit_q4_2025','marketing','en_US','New: Reach high-intent shoppers on Reddit','Sync your catalog and pixel with Reddit for WooCommerce. Launch your ads faster on Reddit and connect with their 400M+ weekly active users and shoppers who turn to this platform for authentic conversations and recommendations.','{}','pending','woocommerce.com','2025-11-14 00:24:32',NULL,0,'plain','',0,0,'info'),(134,'bfcm_general_sale_q4_2025','marketing','en_US','Save up to 40% on extensions and themes','For a limited time, take up to 40% off nearly everything in our Marketplace. It’s the perfect moment to give your store a holiday boost and level up for 2026. Sale ends December 2, 2025, at 14:00 UTC.','{}','pending','woocommerce.com','2025-11-19 16:08:16',NULL,0,'plain','',0,0,'info'),(135,'paypal-carding-recaptcha-dec-25','update','en_US','Activate PayPal fraud management','PayPal detected increased suspicious card activity in market. Please enable fraud protection in your PayPal Payment settings by enabling CAPTCHA for PayPal Payments.','{}','unactioned','woocommerce.com','2025-12-04 17:45:52',NULL,0,'plain','',0,0,'info'),(136,'Googleupdate_q4_2025','marketing','en_US','Make every ad dollar count this holiday season','Google for WooCommerce now includes Budget Recommendations. Install the latest version and get personalized suggestions on where to optimize campaign budgets to reach more holiday shoppers this season.','{}','pending','woocommerce.com','2025-12-05 00:35:29',NULL,0,'plain','',0,0,'info'),(137,'ppcp-recaptcha-protection-note','info','en_US','Activate PayPal fraud management','PayPal detected increased suspicious card activity in market. Please enable fraud protection in your PayPal Payment settings by enabling CAPTCHA for PayPal Payments.','{}','unactioned','woocommerce-paypal-payments/woocommerce-paypal-payments.php','2025-12-09 13:33:54',NULL,0,'plain','',0,0,'info'),(138,'holiday_shipping_deadlines_WCST_2025','marketing','en_US','Holiday shipping deadlines','Ensure your packages arrive before December 25. Verify your exact ship-by date for your destination, carrier, and mail class.','{}','pending','woocommerce.com','2025-12-11 18:42:45',NULL,0,'plain','',0,0,'info'),(139,'holiday_shipping_deadlines_WCS_2025','marketing','en_US','Holiday shipping deadlines','Ensure your packages arrive before December 25. Verify your exact ship-by date for your destination, carrier, and mail class.','{}','pending','woocommerce.com','2025-12-11 18:42:45',NULL,0,'plain','',0,0,'info'),(140,'WC10.4.3-security-update-12-22-2025','update','en_US','An important update is required for WooCommerce','<strong>Please update to WooCommerce 10.4.3 to resolve a security issue.</strong> This update addresses an issue with the WooCommerce Store API that may have made guest order information visible to other logged in users. See the <a href=\"https://developer.woocommerce.com/2025/12/22/store-api-vulnerability-patched-in-woocommerce-8-1/\" target=\"_blank\">Woo Developer blog</a> for more information.','{}','pending','woocommerce.com','2025-12-25 18:45:19',NULL,0,'plain','',0,0,'info'),(141,'ppcp-recaptcha-protection-note12','info','en_US','Fraud protection is now required — enable today','Card networks like Visa, Mastercard and American Express now require fraud prevention controls, and non-compliance may result in fines and processing restrictions. Please enable reCAPTCHA in your PayPal Payments settings to help protect your store and maintain compliance.','{}','unactioned','woocommerce-paypal-payments/woocommerce-paypal-payments.php','2026-01-16 02:23:27',NULL,0,'plain','',0,0,'info'),(142,'paypal-carding-recaptcha-jan-26','update','en_US','Fraud protection is now required — enable today','Card networks like Visa and Mastercard now require fraud prevention controls, and non-compliance may result in fines and processing restrictions. Please enable reCAPTCHA in your PayPal Payments settings to help protect your store and maintain compliance.','{}','unactioned','woocommerce.com','2026-01-22 21:19:06',NULL,0,'plain','',0,0,'info'),(143,'existing_square_bitcoin_promotion_q1_2026','marketing','en_US','Take bitcoin payments in Square with 0% fees in 2026','Your Square POS can now accept in-person bitcoin payments, with near-instant settlement and no chargebacks. Enable it today and pay zero fees through 2026. T&amp;Cs apply.','{}','pending','woocommerce.com','2026-01-22 21:19:06',NULL,0,'plain','',0,0,'info'),(144,'prospects_square_bitcoin_promotion_q1_2026','marketing','en_US','Take bitcoin payments in Square with 0% fees in 2026','Accept in-person <a href=\"https://woocommerce.com/posts/square-bitcoin-launch\">bitcoin payments</a> with Square POS — and pay zero fees on all bitcoin transactions through 2026. Get near-instant settlement and total protection from chargebacks.','{}','pending','woocommerce.com','2026-01-22 21:19:06',NULL,0,'plain','',0,0,'info'),(145,'wc-admin-scheduled-updates-promotion','info','en_US','Analytics now supports scheduled updates','This provides improved performance to your store, enable it in Analytics &gt; Settings.','{}','unactioned','woocommerce-admin','2026-03-06 11:23:28',NULL,0,'plain','',0,0,'info'),(146,'RIN-WC-Security-Update-admin-update-March-2026','update','en_US','An important update is required for WooCommerce','<strong>Update to WooCommerce 10.5.3 or the latest version to resolve a security issue.</strong> This update addresses a vulnerability in WooCommerce versions 5.4 to 10.5.2 that could have permitted unauthorized admin account access. See the <a href=\"https://developer.woocommerce.com/2026/03/02/store-api-vulnerability-patched-in-woocommerce-5-4/\" target=\"_blank\">Woo Developer blog</a> for more information.','{}','pending','woocommerce.com','2026-03-06 11:23:28',NULL,0,'plain','',0,0,'info'),(147,'USPS_Scan_Form_Mar2026','marketing','en_US','New: Save time shipping with USPS SCAN Form','USPS SCAN Form consolidates multiple shipments into one scannable sheet. Hand off all your orders at once — no more scanning packages individually. Select “Create SCAN Form” under your orders to try it today.','{}','pending','woocommerce.com','2026-03-11 19:11:52',NULL,0,'plain','',0,0,'info'),(148,'reddit_q1_2026','marketing','en_US','Start advertising on Reddit with a $500 bonus','Make the most of our new Reddit integration with $500 in Reddit Ads! For a limited time, new advertisers who spend $500 in Reddit Ads Manager over 30 days will get $500 in ad credit. Your bonus credit unlocks automatically when you hit $500 in spend. Use your credit within 30 days.','{}','pending','woocommerce.com','2026-04-01 06:38:14',NULL,0,'plain','',0,0,'info'),(149,'ppcp-working-capital-inbox-note','info','en_US','PayPal Working Capital','Business loans from $1k to $230k for first-time borrowers. Looking to fuel your business growth? With a PayPal Working Capital loan, approved loans are funded in minutes and repaid as a share of your sales. Minimum payment required every 90 days. The lender for PayPal Working Capital is WebBank.','{}','unactioned','woocommerce-paypal-payments','2026-04-06 01:56:26',NULL,0,'plain','',0,0,'info');
